import{_ as e,c as s,o as t,a4 as o}from"./chunks/framework.D5y910bP.js";const f=JSON.parse('{"title":"Refresh Tokens in JWT Authentication","description":"","frontmatter":{"date":"2024-12-16T00:00:00.000Z","tags":["jwt","authentication","webapp","refresh tokens","sessions"],"title":"Refresh Tokens in JWT Authentication"},"headers":[],"relativePath":"blog/jwt-refresh-tokens.md","filePath":"blog/jwt-refresh-tokens.md","lastUpdated":1739289997000}'),a={name:"blog/jwt-refresh-tokens.md"},i=o('<h1 id="refresh-tokens-in-jwt-authentication" tabindex="-1">Refresh Tokens in JWT Authentication <a class="header-anchor" href="#refresh-tokens-in-jwt-authentication" aria-label="Permalink to &quot;Refresh Tokens in JWT Authentication&quot;">​</a></h1><p>Common refresh token strategies used in backend services for JWT token based authentication.</p><ul><li>JWT Token - Short lived tokens with user details and other metadata.</li><li>Refresh Token - Long lived tokens used to get new JWT tokens.</li></ul><h2 id="firebase" tabindex="-1">Firebase <a class="header-anchor" href="#firebase" aria-label="Permalink to &quot;Firebase&quot;">​</a></h2><details class="details custom-block"><summary>Firebase Docs</summary><p>Firebase Authentication sessions are long lived. Every time a user signs in, the user credentials are sent to the Firebase Authentication backend and exchanged for a Firebase ID token (a JWT) and refresh token. Firebase ID tokens are short lived and last for an hour; the refresh token can be used to retrieve new ID tokens. Refresh tokens expire only when one of the following occurs:</p><p>The user is deleted The user is disabled A major account change is detected for the user. This includes events like password or email address updates. The Firebase Admin SDK provides the ability to revoke refresh tokens for a specified user. In addition, an API to check for ID token revocation is also made available. With these capabilities, you have more control over user sessions. The SDK provides the ability to add restrictions to prevent sessions from being used in suspicious circumstances, as well as a mechanism for recovery from potential token theft.</p><p><a href="https://firebase.google.com/docs/auth/admin/manage-sessions" target="_blank" rel="noreferrer">Read more</a></p></details><ul><li>JWT Tokens(called ID Tokens) valid upto 1hr</li><li>Refresh Tokens never expire</li><li>Refresh Tokens stored in the database <ul><li>Can be revoked</li><li>Login on multiple devices can be managed</li></ul></li><li>Refresh Tokens can be used to get new JWT Tokens</li><li>SDK automatically refreshes the token internally - <code>auth.currentUser.getIdToken(/ forceRefresh / true)</code></li><li>Other ways - <a href="https://stackoverflow.com/questions/38233687/how-to-use-the-firebase-refreshtoken-to-reauthenticate" target="_blank" rel="noreferrer">https://stackoverflow.com/questions/38233687/how-to-use-the-firebase-refreshtoken-to-reauthenticate</a></li></ul><h2 id="supabase" tabindex="-1">Supabase <a class="header-anchor" href="#supabase" aria-label="Permalink to &quot;Supabase&quot;">​</a></h2><details class="details custom-block"><summary>Docs</summary><p><a href="https://supabase.com/docs/guides/auth/sessions" target="_blank" rel="noreferrer">Read more</a></p></details><ul><li>JWT tokens(called access token) valid 5min-1hr</li><li>Session = Session ID + (JWT Token + Refresh Token), stored in <code>auth.sessions</code> table.</li><li><code>session_id</code> in jwt claim</li><li>Session created on sign-in</li><li>Refresh token can only be used once to get a new (JWT Token + Refresh Token) pair (todo does it have the same session id?)</li><li>Session termination <ul><li>The user clicks sign out.</li><li>The user changes their password or performs a security sensitive action.</li><li>It times out due to inactivity.</li><li>It reaches its maximum lifetime.</li><li>A user signs in on another device.</li></ul></li><li>Session expiry and limit number of allowed sessions. (Paid feature lol) <ul><li>Time-boxed sessions, which terminate after a fixed amount of time.</li><li>Set an inactivity timeout, which terminates sessions that haven&#39;t been refreshed within the timeout duration.</li><li>Enforce a single-session per user, which only keeps the most recently active session.</li></ul></li></ul><h2 id="aws-cognito" tabindex="-1">AWS Cognito <a class="header-anchor" href="#aws-cognito" aria-label="Permalink to &quot;AWS Cognito&quot;">​</a></h2><details class="details custom-block"><summary>AWS Cognito Docs</summary><p><a href="https://docs.aws.amazon.com/cognito/latest/developerguide/amazon-cognito-user-pools-using-the-refresh-token.html" target="_blank" rel="noreferrer">Read more</a></p></details><p>Same as firebase but</p><ul><li>Refresh Tokens are valid for 30 days by default (can be changed)</li><li>Also has <code>UnusedAccountValidityDays</code></li><li>Has SDK?</li></ul><h2 id="pocketbase" tabindex="-1">PocketBase <a class="header-anchor" href="#pocketbase" aria-label="Permalink to &quot;PocketBase&quot;">​</a></h2><details class="details custom-block"><summary>Pocketbase Docs</summary><p>No docs related to that</p><ul><li><a href="https://github.com/pocketbase/pocketbase/discussions/2154#discussioncomment-5425468" target="_blank" rel="noreferrer">https://github.com/pocketbase/pocketbase/discussions/2154#discussioncomment-5425468</a></li></ul></details><p>From what I found from reading the code</p><ul><li>No refresh token per-se. Tokens can be used to get new tokens</li><li>No tokens stored in database.</li><li>Token key stored in the users table (added to the jwt secret). Can be changed to revoke tokens.</li><li>Hits DB for the token validation on every request to get the secret</li><li>Token expiry = refresh token expiry. Can get a new token as long as the old one is valid.</li></ul><p>Superuser UI refreshes the token automatically when receiving 403 from the server.</p>',18),n=[i];function r(l,h,c,d,u,m){return t(),s("div",null,n)}const b=e(a,[["render",r]]);export{f as __pageData,b as default};
